    seen, pages = self.all_pages("limit=20")
    self.assertEqual(len(pages), 7)
    self.assertEqual([len(page["items"]) for page in pages], [20, 20, 20, 20, 20, 20, 5])
    self.assertEqual(seen, sorted(ids))
